    if isinstance(optimizer, RMSprop):
        version = 1
        checkpoint = dump_checkpoint(parameters, optimizer)
    elif isinstance(optimizer, Adamax):
        version = 2
        checkpoint = dump_checkpoint(parameters, optimizer)
        Adamax._check_hyperparameters(
            optimizer.lr, optimizer.beta1, optimizer.beta2, optimizer.eps
